 if(game){auto provider=MountedMaterialTextureFileProviderCandidate({std::filesystem::path(game)/"tf"}).provider();MaterialTextureFileResolverCandidate files(provider);auto first=files.resolve(std::string("models/effects/pyro/pilotlight")),second=files.resolve(std::string("models/effects/pyro/pilotlight_motion"));need(first&&second,"read-only actual pilot VTFs unavailable");a=*first;b=*second;secondFrame=0;}
