 ModelRenderInputsCandidate seed;seed.materials.resize(1);seed.materials[0].image={1,1,{0,0,0,255}};auto first=prepareRetainedModelTextureInputsCandidate(seed,{{0,RetainedModelTextureChannelCandidate::Base,a,0,0}}),second=prepareRetainedModelTextureInputsCandidate(seed,{{0,RetainedModelTextureChannelCandidate::Base,b,0,secondFrame}});need(first&&second&&first->materials[0].image.rgba!=second->materials[0].image.rgba,"distinct decoded texture profiles required");return {first,second};
